export default Controls;

import { useRef, useEffect, useCallback } from 'react';
import { ParticleConfig, ParticleItem, ColorTheme, ParticleShape } from '../types';

interface ParticleCanvasProps {
  config: ParticleConfig;
  burstSignal: number;
  clearSignal: number;
  onFpsUpdate?: (fps: number) => void;
}

const THEME_PALETTES: Record<ColorTheme, string[]> = {
  aurora: ['#00f2fe', '#4facfe', '#00ff87', '#60efff', '#a8ff78', '#38ef7d'],
  cyberpunk: ['#ff007f', '#00f0ff', '#ffe600', '#7928ca', '#ff0055', '#39ff14'],
  cosmic: ['#b00eff', '#7b42f6', '#3b82f6', '#ec4899', '#6366f1', '#e0e7ff'],
  sakura: ['#ff758c', '#ff7eb3', '#ffc3a0', '#ffb6c1', '#f68084', '#ffffff'],
  magicGold: ['#ffd242', '#f6b93b', '#ff9f43', '#ffeaa7', '#fff275', '#fa983a'],
};

const SHAPES: ParticleShape[] = ['circle', 'star', 'sparkle'];

const ParticleCanvas = ({
  config,
  burstSignal,
  clearSignal,
  onFpsUpdate,
}: ParticleCanvasProps) => {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const containerRef = useRef<HTMLDivElement | null>(null);

  // パーティクル配列
  const particlesRef = useRef<ParticleItem[]>([]);
  // ポインタ座標
  const pointerRef = useRef<{ x: number; y: number; active: boolean; isDown: boolean }>({
    x: 0,
    y: 0,
    active: false,
    isDown: false,
  });

  // オートパイロット用時間軸
  const autoPilotTimeRef = useRef<number>(0);
  const animationFrameIdRef = useRef<number>(0);
  const fpsStatsRef = useRef<{ frames: number; lastTime: number }>({
    frames: 0,
    lastTime: performance.now(),
  });

  // ランダムヘルパー
  const getRandom = (min: number, max: number) => Math.random() * (max - min) + min;

  // テーマ色取得
  const getRandomColor = useCallback((theme: ColorTheme) => {
    const palette = THEME_PALETTES[theme] || THEME_PALETTES.aurora;
    return palette[Math.floor(Math.random() * palette.length)];
  }, []);

  // 1個のパーティクルを生成
  const createParticle = useCallback(
    (x?: number, y?: number, burst: boolean = false): ParticleItem => {
      const width = canvasRef.current?.width || window.innerWidth;
      const height = canvasRef.current?.height || window.innerHeight;

      const px = x ?? getRandom(0, width);
      const py = y ?? getRandom(0, height);

      let vx = getRandom(-1, 1);
      let vy = getRandom(-1, 1);

      if (burst) {
        const angle = Math.random() * Math.PI * 2;
        const force = getRandom(3, 10);
        vx = Math.cos(angle) * force;
        vy = Math.sin(angle) * force;
      }

      const size = getRandom(
        Math.max(1, config.particleSize * 0.6),
        config.particleSize * 1.5
      );

      const shape = SHAPES[Math.floor(Math.random() * SHAPES.length)];

      return {
        x: px,
        y: py,
        vx,
        vy,
        originX: px,
        originY: py,
        size,
        color: getRandomColor(config.colorTheme),
        alpha: getRandom(0.4, 0.95),
        life: 0,
        maxLife: getRandom(100, 350),
        shape,
      };
    },
    [config.particleSize, config.colorTheme, getRandomColor]
  );

  // パーティクル数を設定値に合わせる
  const syncParticleCount = useCallback(() => {
    const list = particlesRef.current;
    const target = config.particleCount;

    if (list.length < target) {
      const needed = target - list.length;
      for (let i = 0; i < needed; i++) {
        list.push(createParticle());
      }
    } else if (list.length > target) {
      list.splice(target);
    }
  }, [config.particleCount, createParticle]);

  // 星を描く
  const drawStar = (
    ctx: CanvasRenderingContext2D,
    cx: number,
    cy: number,
    spikes: number,
    outerRadius: number,
    innerRadius: number
  ) => {
    let rot = (Math.PI / 2) * 3;
    let x = cx;
    let y = cy;
    const step = Math.PI / spikes;

    ctx.beginPath();
    ctx.moveTo(cx, cy - outerRadius);
    for (let i = 0; i < spikes; i++) {
      x = cx + Math.cos(rot) * outerRadius;
      y = cy + Math.sin(rot) * outerRadius;
      ctx.lineTo(x, y);
      rot += step;

      x = cx + Math.cos(rot) * innerRadius;
      y = cy + Math.sin(rot) * innerRadius;
      ctx.lineTo(x, y);
      rot += step;
    }
    ctx.lineTo(cx, cy - outerRadius);
    ctx.closePath();
    ctx.fill();
  };

  // キラキラを描く (十字スパーク)
  const drawSparkle = (
    ctx: CanvasRenderingContext2D,
    cx: number,
    cy: number,
    size: number
  ) => {
    ctx.beginPath();
    ctx.arc(cx, cy, size * 0.4, 0, Math.PI * 2);
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(cx - size * 1.8, cy);
    ctx.lineTo(cx + size * 1.8, cy);
    ctx.moveTo(cx, cy - size * 1.8);
    ctx.lineTo(cx, cy + size * 1.8);
    ctx.lineWidth = Math.max(1, size * 0.35);
    ctx.stroke();
  };

  // メインループ
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    let isMounted = true;

    // リサイズ処理 (Retina対応)
    const resizeCanvas = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const width = window.innerWidth;
      const height = window.innerHeight;

      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;

      ctx.scale(dpr, dpr);

      // 背景を真っ暗にリセット
      ctx.fillStyle = '#04050a';
      ctx.fillRect(0, 0, width, height);
    };

    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);

    // 初期パーティクル
    syncParticleCount();

    const render = (currentTime: number) => {
      if (!isMounted) return;

      const width = window.innerWidth;
      const height = window.innerHeight;

      // FPS計算
      fpsStatsRef.current.frames++;
      if (currentTime - fpsStatsRef.current.lastTime >= 1000) {
        if (onFpsUpdate) {
          onFpsUpdate(fpsStatsRef.current.frames);
        }
        fpsStatsRef.current.frames = 0;
        fpsStatsRef.current.lastTime = currentTime;
      }

      // 残像フェード (trailLengthに応じて透過度制御: 1=薄い残像, 10=長い残像)
      // trailLength: 1 -> alpha 0.40, 10 -> alpha 0.06
      const fadeAlpha = 0.42 - (config.trailLength / 10) * 0.35;
      ctx.globalCompositeOperation = 'source-over';
      ctx.fillStyle = `rgba(4, 5, 10, ${fadeAlpha})`;
      ctx.fillRect(0, 0, width, height);

      // パーティクル重なり発光
      ctx.globalCompositeOperation = 'lighter';

      // ポインタターゲット座標の決定
      let targetX = pointerRef.current.x;
      let targetY = pointerRef.current.y;
      let isTargetActive = pointerRef.current.active;

      // オートパイロット計算 (ポインタ非アクティブ または autoPilot=true かつ 非タッチ時)
      if (config.autoPilot && (!pointerRef.current.active || !pointerRef.current.isDown)) {
        autoPilotTimeRef.current += 0.015 * config.speed;
        const t = autoPilotTimeRef.current;
        const centerX = width / 2;
        const centerY = height / 2;
        const radiusX = Math.min(centerX * 0.75, 420);
        const radiusY = Math.min(centerY * 0.65, 300);

        // リサージュ図形曲線
        targetX = centerX + Math.sin(t) * radiusX;
        targetY = centerY + Math.sin(t * 1.5) * Math.cos(t * 0.5) * radiusY;
        isTargetActive = true;
      }

      const particles = particlesRef.current;
      const count = particles.length;

      // パーティクル更新 & 描画
      for (let i = 0; i < count; i++) {
        const p = particles[i];

        // 相互作用の計算
        if (isTargetActive) {
          const dx = targetX - p.x;
          const dy = targetY - p.y;
          const dist = Math.sqrt(dx * dx + dy * dy) || 1;

          if (config.mode === 'attract') {
            // 中心へ引き寄せ
            const force = Math.min(8, (260 / dist) * config.speed);
            p.vx += (dx / dist) * force * 0.12;
            p.vy += (dy / dist) * force * 0.12;
          } else if (config.mode === 'repel') {
            // 反発
            if (dist < 220) {
              const force = ((220 - dist) / 220) * 6 * config.speed;
              p.vx -= (dx / dist) * force * 0.35;
              p.vy -= (dy / dist) * force * 0.35;
            }
          } else if (config.mode === 'vortex') {
            // 渦巻力 (回転 + 引力)
            const force = Math.min(6, (280 / dist) * config.speed);
            // 接線ベクトル
            const perpX = -dy / dist;
            const perpY = dx / dist;
            p.vx += perpX * force * 0.35 + (dx / dist) * 0.25;
            p.vy += perpY * force * 0.35 + (dy / dist) * 0.25;
          } else if (config.mode === 'trail') {
            // クリックやドラッグ軌跡
            if (pointerRef.current.isDown && dist < 120) {
              p.vx += (getRandom(-2, 2) * config.speed);
              p.vy += (getRandom(-2, 2) * config.speed);
            }
          }
        }

        // 自然減衰 (摩擦)
        p.vx *= 0.94;
        p.vy *= 0.94;

        // 速度制限
        const speedMax = 14 * config.speed;
        p.vx = Math.max(-speedMax, Math.min(speedMax, p.vx));
        p.vy = Math.max(-speedMax, Math.min(speedMax, p.vy));

        // 移動
        p.x += p.vx * config.speed;
        p.y += p.vy * config.speed;

        // 寿命カウント
        p.life++;
        if (p.life > p.maxLife) {
          // リスポーン
          if (isTargetActive && config.mode === 'trail' && Math.random() < 0.6) {
            p.x = targetX + getRandom(-20, 20);
            p.y = targetY + getRandom(-20, 20);
            p.vx = getRandom(-2, 2);
            p.vy = getRandom(-2, 2);
          } else {
            p.x = getRandom(0, width);
            p.y = getRandom(0, height);
            p.vx = getRandom(-1, 1);
            p.vy = getRandom(-1, 1);
          }
          p.life = 0;
          p.maxLife = getRandom(100, 350);
          p.color = getRandomColor(config.colorTheme);
        }

        // 画面外ワープ
        if (p.x < -30) p.x = width + 20;
        if (p.x > width + 30) p.x = -20;
        if (p.y < -30) p.y = height + 20;
        if (p.y > height + 30) p.y = -20;

        // 描画
        ctx.fillStyle = p.color;
        ctx.strokeStyle = p.color;
        ctx.globalAlpha = p.alpha;

        const currentSize = Math.max(1, p.size * (1 - p.life / (p.maxLife * 1.5)));

        if (p.shape === 'star') {
          drawStar(ctx, p.x, p.y, 5, currentSize * 1.8, currentSize * 0.8);
        } else if (p.shape === 'sparkle') {
          drawSparkle(ctx, p.x, p.y, currentSize * 1.6);
        } else {
          ctx.beginPath();
          ctx.arc(p.x, p.y, currentSize, 0, Math.PI * 2);
          ctx.fill();
        }
      }

      ctx.globalAlpha = 1.0;
      animationFrameIdRef.current = requestAnimationFrame(render);
    };

    animationFrameIdRef.current = requestAnimationFrame(render);

    return () => {
      isMounted = false;
      cancelAnimationFrame(animationFrameIdRef.current);
      window.removeEventListener('resize', resizeCanvas);
    };
  }, [config, getRandomColor, syncParticleCount]);

  // 設定変更時のパーティクル数同期
  useEffect(() => {
    syncParticleCount();
  }, [syncParticleCount]);

  // テーマ切り替え時に全パーティクルの色を即座に更新
  useEffect(() => {
    particlesRef.current.forEach((p) => {
      p.color = getRandomColor(config.colorTheme);
    });
  }, [config.colorTheme, getRandomColor]);

  // 爆発シグナル検知
  useEffect(() => {
    if (burstSignal === 0) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    const width = window.innerWidth;
    const height = window.innerHeight;
    const originX = pointerRef.current.active ? pointerRef.current.x : width / 2;
    const originY = pointerRef.current.active ? pointerRef.current.y : height / 2;

    const burstCount = Math.min(180, Math.floor(config.particleCount * 0.3));
    for (let i = 0; i < burstCount; i++) {
      particlesRef.current.push(createParticle(originX, originY, true));
    }

    // 数が増えすぎたら上限調整
    if (particlesRef.current.length > config.particleCount * 1.5) {
      particlesRef.current.splice(0, particlesRef.current.length - config.particleCount);
    }
  }, [burstSignal, config.particleCount, createParticle]);

  // クリアシグナル検知
  useEffect(() => {
    if (clearSignal === 0) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (ctx) {
      ctx.globalCompositeOperation = 'source-over';
      ctx.fillStyle = '#04050a';
      ctx.fillRect(0, 0, window.innerWidth, window.innerHeight);
    }

    particlesRef.current = [];
    syncParticleCount();
  }, [clearSignal, syncParticleCount]);

  // ポインターイベントハンドラー
  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    pointerRef.current = {
      x: e.clientX,
      y: e.clientY,
      active: true,
      isDown: true,
    };

    // タップ位置で小バースト
    const tapCount = 20;
    for (let i = 0; i < tapCount; i++) {
      particlesRef.current.push(createParticle(e.clientX, e.clientY, true));
    }
    if (particlesRef.current.length > config.particleCount + 60) {
      particlesRef.current.splice(0, 20);
    }
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    pointerRef.current.x = e.clientX;
    pointerRef.current.y = e.clientY;
    pointerRef.current.active = true;

    // トレイルモード中の軌跡追加
    if (pointerRef.current.isDown && config.mode === 'trail') {
      for (let i = 0; i < 3; i++) {
        const p = createParticle(
          e.clientX + getRandom(-10, 10),
          e.clientY + getRandom(-10, 10),
          false
        );
        p.vx = getRandom(-1.5, 1.5);
        p.vy = getRandom(-1.5, 1.5);
        particlesRef.current.push(p);
      }
      if (particlesRef.current.length > config.particleCount + 60) {
        particlesRef.current.splice(0, 3);
      }
    }
  };

  const handlePointerUp = () => {
    pointerRef.current.isDown = false;
  };

  const handlePointerLeave = () => {
    pointerRef.current.active = false;
    pointerRef.current.isDown = false;
  };

  return (
    <div
      ref={containerRef}
      className="canvas-container"
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerLeave={handlePointerLeave}
      onPointerCancel={handlePointerLeave}
    >
      <canvas ref={canvasRef} className="particle-canvas" />
    </div>
  );
};

export default ParticleCanvas;

import { useState, useCallback } from 'react';
import {
  Sparkles,
  Sliders,
  Flame,
  RotateCcw,
  MousePointer,
  Compass,
} from 'lucide-react';
import { ParticleConfig } from './types';
import ParticleCanvas from './components/ParticleCanvas';
import Controls from './components/Controls';
import './index.css';

const DEFAULT_CONFIG: ParticleConfig = {
  colorTheme: 'aurora',
  mode: 'vortex',
  particleCount: 500,
  speed: 1.8,
  particleSize: 3.5,
  trailLength: 7,
  autoPilot: true,
};

const MODE_LABELS: Record<string, string> = {
  attract: '引力',
  repel: '斥力',
  vortex: '渦潮',
  trail: '軌跡',
};

const THEME_LABELS: Record<string, string> = {
  aurora: 'オーロラ',
  cyberpunk: 'サイバー',
  cosmic: 'コズミック',
  sakura: 'サクラ',
  magicGold: 'ゴールド',
};

const App = () => {
  const [config, setConfig] = useState<ParticleConfig>(DEFAULT_CONFIG);
  const [isPanelOpen, setIsPanelOpen] = useState<boolean>(false);
  const [burstSignal, setBurstSignal] = useState<number>(0);
  const [clearSignal, setClearSignal] = useState<number>(0);
  const [fps, setFps] = useState<number>(60);

  // 設定更新ハンドラー
  const handleConfigChange = useCallback((newConfig: Partial<ParticleConfig>) => {
    setConfig((prev) => ({ ...prev, ...newConfig }));
  }, []);

  // 爆発ハンドラー
  const handleBurst = useCallback(() => {
    setBurstSignal((prev) => prev + 1);
  }, []);

  // 画面クリアハンドラー
  const handleClear = useCallback(() => {
    setClearSignal((prev) => prev + 1);
  }, []);

  // パネル開閉
  const handleTogglePanel = useCallback(() => {
    setIsPanelOpen((prev) => !prev);
  }, []);

  // 次のモードへ素早くトグル
  const handleCycleMode = () => {
    const modes: ParticleConfig['mode'][] = ['attract', 'repel', 'vortex', 'trail'];
    const currentIndex = modes.indexOf(config.mode);
    const nextIndex = (currentIndex + 1) % modes.length;
    handleConfigChange({ mode: modes[nextIndex] });
  };

  return (
    <main className="app-container">
      {/* 高性能パーティクルキャンバス */}
      <ParticleCanvas
        config={config}
        burstSignal={burstSignal}
        clearSignal={clearSignal}
        onFpsUpdate={setFps}
      />

      {/* 左上ヘッダーオーバーレイ */}
      <header className="header-overlay">
        <h1 className="app-title">
          <Sparkles size={22} style={{ color: '#00f2fe' }} />
          <span>Lumina Trails</span>
          <span className="app-badge">Interactive FX</span>
        </h1>
        <div className="instruction-banner">
          <MousePointer size={14} />
          <span>マウス・指先</span>で画面をなぞる、またはタップして光を放ちます
        </div>
      </header>

      {/* 画面下部クイックアクションツールバー */}
      <nav className="floating-toolbar" aria-label="クイック操作ツールバー">
        <div className="stat-badge" title="現在のFPSと粒子数">
          <strong>{fps}</strong> FPS / <strong>{config.particleCount}</strong> 粒子
        </div>

        {/* クイックモード切替 */}
        <button
          type="button"
          className="action-btn"
          onClick={handleCycleMode}
          title="クリックでモードを切り替え"
        >
          <Compass size={15} />
          <span>{MODE_LABELS[config.mode]}モード</span>
        </button>

        {/* 光の爆発ボタン */}
        <button
          type="button"
          className="action-btn action-btn-primary"
          onClick={handleBurst}
          title="光を爆発させる"
        >
          <span className="action-btn-icon">
            <Flame size={16} />
          </span>
          <span>バースト</span>
        </button>

        {/* リセットボタン */}
        <button
          type="button"
          className="action-btn"
          onClick={handleClear}
          title="画面をリセット"
        >
          <span className="action-btn-icon">
            <RotateCcw size={15} />
          </span>
          <span>リセット</span>
        </button>

        {/* 設定パネル開閉ボタン */}
        <button
          type="button"
          className="action-btn"
          onClick={handleTogglePanel}
          title="詳細設定を開く"
        >
          <span className="action-btn-icon">
            <Sliders size={15} />
          </span>
          <span>設定</span>
        </button>
      </nav>

      {/* 右側ドロワー設定パネル */}
      <Controls
        config={config}
        onChangeConfig={handleConfigChange}
        onBurst={handleBurst}
        onClear={handleClear}
        isPanelOpen={isPanelOpen}
        onTogglePanel={handleTogglePanel}
      />
    </main>
  );
};

export default App;
